using TownOfHost;
using TownOfHost.Modules;
using TownOfHost.Roles.Core;
using TownOfHost.Roles.Core.Interfaces;
using TownOfHost.Roles.Neutral;
class Program
{
 static int passed, failed;
 static void Check(bool b,string why="assertion failed"){if(!b)throw new Exception(why);}
 static void Test(string name,Action body){try{Reset();body();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
 static void Reset(){AmongUsClient.Instance.AmHost=true;LessThan.Reset();CustomRoleManager.AllActiveRoles.Clear();CustomRoleManager.Suicides=0;PlayerCatch.Players.Clear();TestOptions.All.Clear();SoloWinOption.AllData.Clear();LessThan.RoleInfo.OptionCreator();CustomWinnerHolder.Reset();Logger.Messages.Clear();AmongUsClient.Instance.Sent.Clear();UtilsNotifyRoles.Calls.Clear();IRandom.Instance=new TestRandom();GameStates.InGame=GameStates.IsInTask=true;GameStates.Intro=GameStates.IsMeeting=GameStates.IsOutro=GameStates.ExiledAnimate=false;SelfVoteManager.Allowed=true;TownOfHost.Roles.AddOns.Common.Amnesia.Blocked.Clear();MeetingHud.Instance=null;ChatUpdatePatch.BlockSendName=false;NameColorManager.Calls.Clear();PlayerControl.LocalPlayer=PC(0);}
 static PlayerControl PC(byte id){var p=new PlayerControl{PlayerId=id,NetId=(uint)(id+100),ClientId=20+id};PlayerCatch.Players[id]=p;return p;}
 static OptionItem Opt(string name)=>TestOptions.All[name];
 static void Set(string name,float value)=>Opt(name).Value=value;
 static LessThan Make(int own=62,int theirs=37,int extra=0){PC(1);for(int n=0;n<extra;n++)PC((byte)(2+n));((TestRandom)IRandom.Instance).Values=new(new[]{own,theirs}.Concat(Enumerable.Repeat(50,extra)));var r=new LessThan(PlayerControl.LocalPlayer);r.Add();return r;}
 static int Number(byte id){Check(LessThan.TryGetNumber(PlayerCatch.GetPlayerById(id),out int n));return n;}
 static void Meeting(params LessThan[] roles){MeetingHud.Instance=new();GameStates.IsMeeting=true;GameStates.IsInTask=false;foreach(var r in roles)r.OnStartMeeting();}
 static void EndMeeting(params LessThan[] roles){foreach(var r in roles)r.AfterMeetingTasks();GameStates.IsMeeting=false;GameStates.IsInTask=true;MeetingHud.Instance=null;}
 static void Vote(LessThan r,bool intentional=true,byte? original=null,byte? final=null)=>LessThan.OnAcceptedVote(r.Player.PlayerId,original??r.Player.PlayerId,final??r.Player.PlayerId,intentional);
 static MurderInfo Attempt(LessThan r,PlayerControl target,int guard=0,bool can=true,bool doKill=true){var info=new MurderInfo{AttemptKiller=r.Player,AttemptTarget=target,GuardPower=guard,CanKill=can,DoKill=doKill};r.OnCheckMurderAsKiller(info);if(info.CanKill&&info.DoKill&&info.KillPower>info.GuardPower)target.Data.IsDead=true;return info;}
 static void ExistingWinner(int priority){SoloWinOption.AllData[CustomRoles.Tiger]=new(){OptionWin=new(){Value=priority}};CustomWinnerHolder.ResetAndSetWinner(CustomWinner.Tiger);}
 static void Main()
 {
 Test("metadata ID376 neutral desync Impostor Shell color and source",()=>{var i=LessThan.RoleInfo;Check((int)i.RoleName==376&&i.Team==CustomRoleTypes.Neutral&&i.BaseRoleType()==AmongUs.GameOptions.RoleTypes.Impostor&&i.Desync&&i.CountType==CountTypes.LessThan&&i.ConfigId==40300&&i.ChatCommand=="lst"&&i.From==From.TownOfHost_Shell&&i.New);});
 Test("eight option IDs defaults and all numeric rules",()=>{Check(TestOptions.All.Count==8);Check(TestOptions.All.Values.Select(x=>x.Id).SequenceEqual(Enumerable.Range(40309,8)));Check(Opt("KillCooldown").Rule.Equals(new ClampedFloatValueRule(2.5f,100,2.5f))&&Opt("KillCooldown").Value==20);Check(Opt("SoloWinOption").Rule.Equals(new ClampedIntegerValueRule(1,30,1))&&Opt("SoloWinOption").Value==15);Check(Opt("LessThanRerollUses").Rule.Equals(new ClampedIntegerValueRule(1,10,1))&&Opt("LessThanRerollUses").Value==1);foreach(var key in new[]{"LessThanShowNumber","CanVent","LessThanReroll","LessThanResetEachMeeting"})Check(Opt(key).GetBool());Check(!Opt("LessThanRerollOthers").GetBool());});
 Test("reroll children use existing parent option",()=>{foreach(var key in new[]{"LessThanRerollUses","LessThanResetEachMeeting","LessThanRerollOthers"})Check(ReferenceEquals(Opt(key).Parent,Opt("LessThanReroll")));});
 Test("all players including caster receive independent inclusive values",()=>{var r=Make(1,100,8);Check(PlayerCatch.AllPlayerControls.Count()==10);Check(Number(0)==1&&Number(1)==100);foreach(var pc in PlayerCatch.AllPlayerControls)Check(LessThan.TryGetNumber(pc,out int n)&&n>=1&&n<=100);Check(((TestRandom)IRandom.Instance).Calls==10);});
 Test("all one hundred possible values accepted and out of range rejected",()=>{var state=new LessThanNumbers();for(int n=1;n<=100;n++){state.Assign(0,()=>n);Check(state.TryGet(0,out int x)&&x==n);}foreach(int n in new[]{-1,0,101,int.MaxValue}){bool threw=false;try{state.Assign(0,()=>n);}catch(ArgumentOutOfRangeException){threw=true;}Check(threw);}});
 Test("duplicate values are allowed and compare equality explicit",()=>{Make(62,62);Check(Number(0)==Number(1));for(int a=1;a<=100;a++)for(int b=1;b<=100;b++)Check(LessThanNumbers.Compare(a,b)==Math.Sign(a-b));});
 Test("spawn does not redraw existing values",()=>{var r=Make();int calls=((TestRandom)IRandom.Instance).Calls;r.OnSpawn();r.OnSpawn(true);Check(Number(0)==62&&Number(1)==37&&((TestRandom)IRandom.Instance).Calls==calls);});
 Test("a new participant receives a number without redrawing others",()=>{var r=Make();PC(2);r.OnSpawn();Check(Number(0)==62&&Number(1)==37&&Number(2)==50);});
 Test("same native player through another CLR wrapper preserves number",()=>{var r=Make();var old=PlayerCatch.GetPlayerById(1);PlayerCatch.Players[1]=new(){PlayerId=1,NativeId=old.NativeId,Data=old.Data};r.OnSpawn();Check(Number(1)==37);});
 Test("reused player ID receives a new number and old wrapper is rejected",()=>{var r=Make();var old=PlayerCatch.GetPlayerById(1);PC(1);r.OnSpawn();Check(Number(1)==50&&!LessThan.TryGetNumber(old,out _));});
 Test("host-only ledger never accepts client data",()=>{var r=Make();AmongUsClient.Instance.AmHost=false;Check(!LessThan.TryGetNumber(r.Player,out _));r.ReceiveRPC(new(true,99));AmongUsClient.Instance.AmHost=true;Check(Number(0)==62);});
 Test("end round clears values and hides number",()=>{var r=Make();LessThan.EndRound();Check(!LessThan.TryGetNumber(r.Player,out _)&&r.GetMark(r.Player)=="");});
 Test("next round has fresh numbers and no previous usage",()=>{var r=Make();Meeting(r);Vote(r);LessThan.EndRound();CustomRoleManager.AllActiveRoles.Clear();GameStates.IsMeeting=false;GameStates.IsInTask=true;((TestRandom)IRandom.Instance).Values=new(new[]{7,8});var next=new LessThan(PlayerControl.LocalPlayer);next.Add();Check(Number(0)==7&&Number(1)==8);Meeting(next);Vote(next);Check(Number(0)==50);});
 Test("larger number kills original target only",()=>{var r=Make();var target=PlayerCatch.GetPlayerById(1);var info=Attempt(r,target);Check(target.Data.IsDead&&!r.Player.Data.IsDead&&info.AttemptTarget==target&&CustomRoleManager.Suicides==0);});
 Test("smaller number suicides without killing target",()=>{var r=Make(37,62);var target=PlayerCatch.GetPlayerById(1);var info=Attempt(r,target);Check(r.Player.Data.IsDead&&!target.Data.IsDead&&!info.DoKill&&CustomRoleManager.Suicides==1);});
 Test("equal number neither dies and cooldown is consumed",()=>{var r=Make(62,62);var target=PlayerCatch.GetPlayerById(1);Check(!Attempt(r,target).DoKill&&!target.Data.IsDead&&!r.Player.Data.IsDead&&r.Player.CooldownCalls==1);});
 Test("pending guard prevents comparison suicide or cooldown action",()=>{var r=Make(1,100);var target=PlayerCatch.GetPlayerById(1);Attempt(r,target,guard:1);Check(!target.Data.IsDead&&!r.Player.Data.IsDead&&CustomRoleManager.Suicides==0&&r.Player.CooldownCalls==0);});
 Test("CanKill false and DoKill false are respected",()=>{foreach(bool can in new[]{false,true}){Reset();var r=Make(1,100);Attempt(r,PlayerCatch.GetPlayerById(1),can:can,doKill:!can);Check(CustomRoleManager.Suicides==0&&!r.Player.Data.IsDead);}});
 Test("meeting outro intro and game-ended attempts rejected",()=>{for(int n=0;n<5;n++){Reset();var r=Make();if(n==0)GameStates.IsMeeting=true;if(n==1)GameStates.IsOutro=true;if(n==2)GameStates.Intro=true;if(n==3)GameStates.InGame=false;if(n==4)GameStates.CalledMeeting=true;Check(!Attempt(r,PlayerCatch.GetPlayerById(1)).DoKill);}});
 Test("non host cannot commit kill comparison",()=>{var r=Make();AmongUsClient.Instance.AmHost=false;Check(!Attempt(r,PlayerCatch.GetPlayerById(1)).DoKill);});
 Test("missing numbers never allow an ordinary kill",()=>{var r=Make();var newcomer=PC(2);Check(!Attempt(r,newcomer).DoKill&&!newcomer.Data.IsDead);});
 Test("attempt killer mismatch cannot redirect target",()=>{var r=Make();var target=PlayerCatch.GetPlayerById(1);var info=new MurderInfo{AttemptKiller=target,AttemptTarget=r.Player};r.OnCheckMurderAsKiller(info);Check(!info.DoKill&&CustomRoleManager.Suicides==0);});
 Test("repeated failed comparison causes at most one suicide",()=>{var r=Make(1,100);var target=PlayerCatch.GetPlayerById(1);Attempt(r,target);Attempt(r,target);Check(CustomRoleManager.Suicides==1&&!target.Data.IsDead);});
 Test("vent toggle cooldown boundaries and no sabotage",()=>{var r=Make();IKiller killer=r;Check(killer.CanUseKillButton()&&killer.CanUseImpostorVentButton()&&!killer.CanUseSabotageButton());Set("CanVent",0);Check(!killer.CanUseImpostorVentButton());foreach(float cd in new[]{2.5f,20,100}){Set("KillCooldown",cd);Check(killer.CalculateKillCooldown()==cd);}});
 Test("accepted self vote rerolls caster only",()=>{var r=Make();Meeting(r);Vote(r);Check(Number(0)==50&&Number(1)==37);});
 Test("non self skipped invalid and unintentional votes do not reroll",()=>{var r=Make();Meeting(r);foreach(byte id in new byte[]{1,253,254,255})Vote(r,original:id,final:id);Vote(r,intentional:false);Check(Number(0)==62);Vote(r);Check(Number(0)==50);});
 Test("vote rewritten from or away from self does not reroll",()=>{var r=Make();Meeting(r);Vote(r,original:1,final:0);Vote(r,original:0,final:1);Check(Number(0)==62);});
 Test("duplicate self vote RPC consumed once even with limit ten",()=>{var r=Make();Set("LessThanRerollUses",10);Meeting(r);Vote(r);int calls=((TestRandom)IRandom.Instance).Calls;for(int n=0;n<10;n++)Vote(r);Check(((TestRandom)IRandom.Instance).Calls==calls);});
 Test("reroll disabled never redraws",()=>{var r=Make();Set("LessThanReroll",0);Meeting(r);Vote(r);Check(Number(0)==62);Set("LessThanReroll",1);Vote(r);Check(Number(0)==62);});
 Test("per meeting reset permits a new use next meeting",()=>{var r=Make();Meeting(r);Vote(r);EndMeeting(r);((TestRandom)IRandom.Instance).Values.Enqueue(80);Meeting(r);Vote(r);Check(Number(0)==80);});
 Test("round-wide limit is not restored next meeting",()=>{var r=Make();Set("LessThanResetEachMeeting",0);Meeting(r);Vote(r);EndMeeting(r);((TestRandom)IRandom.Instance).Values.Enqueue(80);Meeting(r);Vote(r);Check(Number(0)==50);});
 Test("round-wide three uses across meetings expire exactly",()=>{var r=Make();Set("LessThanResetEachMeeting",0);Set("LessThanRerollUses",3);for(int n=0;n<4;n++){Meeting(r);((TestRandom)IRandom.Instance).Values.Enqueue(70+n);Vote(r);Check(Number(0)==(n<3?70+n:72));EndMeeting(r);}});
 Test("duplicate meeting-start callback does not restore uses",()=>{var r=Make();Meeting(r);Vote(r);r.OnStartMeeting();int calls=((TestRandom)IRandom.Instance).Calls;Vote(r);Check(((TestRandom)IRandom.Instance).Calls==calls);});
 Test("reroll can legitimately draw the same number",()=>{var r=Make();Meeting(r);((TestRandom)IRandom.Instance).Values.Enqueue(62);Vote(r);Check(Number(0)==62);int calls=((TestRandom)IRandom.Instance).Calls;Vote(r);Check(((TestRandom)IRandom.Instance).Calls==calls);});
 Test("global reroll changes each living player independently and skips dead",()=>{var r=Make(62,37,1);Set("LessThanRerollOthers",1);PlayerCatch.GetPlayerById(2).Data.IsDead=true;Meeting(r);((TestRandom)IRandom.Instance).Values=new(new[]{1,100});Vote(r);Check(Number(0)==1&&Number(1)==100&&Number(2)==50);});
 Test("multiple LessThans share one ledger but only actor spends use",()=>{var a=Make(62,37,1);var b=new LessThan(PlayerCatch.GetPlayerById(2));b.Add();Set("LessThanRerollOthers",1);Set("LessThanResetEachMeeting",0);Meeting(a,b);Vote(a);((TestRandom)IRandom.Instance).Values=new(new[]{11,12,13});Vote(b);Check(Number(0)==11&&Number(1)==12&&Number(2)==13);});
 Test("dead disconnected and stale owner cannot reroll",()=>{for(int n=0;n<3;n++){Reset();var r=Make();Meeting(r);if(n==0)r.Player.Data.IsDead=true;if(n==1)r.Player.Data.Disconnected=true;if(n==2)CustomRoleManager.AllActiveRoles.Remove(0);Vote(r);Check(((TestRandom)IRandom.Instance).Calls==2);}});
 Test("meeting closed and vote counting over prevents reroll",()=>{var r=Make();Meeting(r);r.AfterMeetingTasks();Vote(r);Check(Number(0)==62);});
 Test("meeting ability restrictions are respected",()=>{var r=Make();Meeting(r);SelfVoteManager.Allowed=false;Vote(r);Check(Number(0)==62);});
 Test("amnesia prevents reroll",()=>{var r=Make();Meeting(r);TownOfHost.Roles.AddOns.Common.Amnesia.Blocked.Add(0);Vote(r);Check(Number(0)==62);});
 Test("changing limit never creates negative remaining usage",()=>{var usage=new LessThanRerollUsage();usage.BeginMeeting();Check(usage.TryUse(10,false));Check(usage.TryUse(10,false));Check(usage.Remaining(1,false)==0&&!usage.TryUse(1,false));usage.BeginMeeting();Check(usage.Remaining(1,true)==1);});
 Test("mark is own-number only with no progress-log leak",()=>{var r=Make();Check(r.GetMark(r.Player).Contains("(62)"));var other=PlayerCatch.GetPlayerById(1);Check(r.GetMark(other)==""&&r.GetMark(r.Player,other)==""&&r.GetMark(other,r.Player)=="");});
 Test("number mark is stable during meeting and after return",()=>{var r=Make();Meeting(r);Check(r.GetMark(r.Player,isForMeeting:true).Contains("(62)"));Vote(r);Check(r.GetMark(r.Player,isForMeeting:true).Contains("(50)"));EndMeeting(r);Check(r.GetMark(r.Player).Contains("(50)"));});
 Test("display toggle hides number and initial outro hides all",()=>{var r=Make();Set("LessThanShowNumber",0);Check(r.GetMark(r.Player)=="");Set("LessThanShowNumber",1);GameStates.Intro=true;Check(r.GetMark(r.Player)=="");GameStates.Intro=false;GameStates.IsOutro=true;Check(r.GetMark(r.Player)=="");});
 Test("remote MOD gets only its own number in targeted existing RPC",()=>{PC(1).Mod=true;((TestRandom)IRandom.Instance).Values=new(new[]{11,77});var r=new LessThan(PlayerCatch.GetPlayerById(1));r.Add();var msg=AmongUsClient.Instance.Sent.Single();Check(msg.Target==21&&msg.Rpc==(byte)CustomRPC.CustomRoleSync&&msg.Values.SequenceEqual(new object[]{(byte)1,true,77}));Check(!msg.Values.Contains(11));});
 Test("invalid client ID never falls back to broadcast",()=>{var pc=PC(1);pc.Mod=true;pc.ClientId=-1;new LessThan(pc).Add();Check(AmongUsClient.Instance.Sent.Count==0);});
 Test("Vanilla owner uses private name notification without custom-number RPC",()=>{var r=new LessThan(PC(1));r.Add();Check(AmongUsClient.Instance.Sent.Count==0&&UtilsNotifyRoles.Calls.All(x=>x.OnlyMe&&x.Seer==r.Player));});
 Test("show off does not serialize hidden value",()=>{Set("LessThanShowNumber",0);var pc=PC(1);pc.Mod=true;new LessThan(pc).Add();Check(AmongUsClient.Instance.Sent.Single().Values.SequenceEqual(new object[]{(byte)1,false}));});
 Test("initial play resends privately once not every tick",()=>{var pc=PC(1);pc.Mod=true;var r=new LessThan(pc);r.Add();int before=AmongUsClient.Instance.Sent.Count;r.OnFixedUpdate(pc);for(int n=0;n<100;n++)r.OnFixedUpdate(pc);Check(AmongUsClient.Instance.Sent.Count==before+1);});
 Test("client displays only owner value without a ledger",()=>{var r=Make();AmongUsClient.Instance.AmHost=false;r.ReceiveRPC(new(true,88));Check(r.GetMark(r.Player).Contains("(88)")&&!LessThan.TryGetNumber(r.Player,out _));r.ReceiveRPC(new(false));Check(r.GetMark(r.Player)=="");});
 Test("invalid client display values rejected",()=>{var r=Make();AmongUsClient.Instance.AmHost=false;r.ReceiveRPC(new(true,60));foreach(int value in new[]{-1,0,101,int.MaxValue})r.ReceiveRPC(new(true,value));Check(r.GetMark(r.Player).Contains("(60)"));});
 Test("foreign role owner cannot update local number display",()=>{var r=new LessThan(PC(1));r.Add();AmongUsClient.Instance.AmHost=false;r.ReceiveRPC(new(true,99));Check(r.GetMark(r.Player)=="");});
 Test("one LessThan one crew wins exactly one player",()=>{var r=Make();Check(LessThan.TryChooseWinner());LessThan.FinalizeSoloWinner();Check(CustomWinnerHolder.WinnerTeam==CustomWinner.LessThan&&CustomWinnerHolder.WinnerIds.SetEquals(new byte[]{0})&&CustomWinnerHolder.WinnerRoles.Count==0);});
 Test("one LessThan two crew does not win",()=>{Make(extra:1);Check(!LessThan.TryChooseWinner()&&CustomWinnerHolder.WinnerTeam==CustomWinner.Default);});
 Test("living Impostor prevents LessThan victory",()=>{Make();PlayerCatch.GetPlayerById(1).Role=CustomRoles.Impostor;Check(!LessThan.TryChooseWinner());});
 Test("living neutral killer prevents victory",()=>{Make();PlayerCatch.GetPlayerById(1).Role=CustomRoles.Jackal;Check(!LessThan.TryChooseWinner());});
 Test("all existing killing-team count types prevent victory",()=>{foreach(var count in new[]{CountTypes.Impostor,CountTypes.Jackal,CountTypes.Remotekiller,CountTypes.GrimReaper,CountTypes.MilkyWay,CountTypes.Pavlov,CountTypes.Eater,CountTypes.Victim,CountTypes.Monika,CountTypes.StandMaster,CountTypes.Villain,CountTypes.Daoshi,CountTypes.Hunter}){Reset();Make();PlayerCatch.GetPlayerById(1).Count=count;Check(!LessThan.TryChooseWinner(),count.ToString());}});
 Test("dead and disconnected killers do not block",()=>{var r=Make(extra:1);var p=PlayerCatch.GetPlayerById(1);p.Role=CustomRoles.Impostor;p.Data.IsDead=true;Check(LessThan.TryChooseWinner());});
 Test("largest LessThan number wins regardless of PlayerId",()=>{var a=Make(10,37,1);((TestRandom)IRandom.Instance).Values.Enqueue(99);var p=PC(2);var b=new LessThan(p);b.Add();Check(Number(2)==99&&LessThan.TryChooseWinner());LessThan.FinalizeSoloWinner();Check(CustomWinnerHolder.WinnerIds.SetEquals(new byte[]{2}));});
 Test("equal largest numbers choose smallest PlayerId",()=>{var a=Make(50,37,1);new LessThan(PlayerCatch.GetPlayerById(2)).Add();Check(LessThan.TryChooseWinner());LessThan.FinalizeSoloWinner();Check(CustomWinnerHolder.WinnerIds.SetEquals(new byte[]{0}));});
 Test("dead LessThan excluded from ratio and winner selection",()=>{var a=Make(90,37,1);var b=new LessThan(PlayerCatch.GetPlayerById(2));b.Add();a.Player.Data.IsDead=true;Check(LessThan.TryChooseWinner());LessThan.FinalizeSoloWinner();Check(CustomWinnerHolder.WinnerIds.SetEquals(new byte[]{2}));});
 Test("no living LessThan never wins",()=>{var r=Make();r.Player.Data.IsDead=true;Check(!LessThan.TryChooseWinner());});
 Test("priority one fifteen thirty use actual existing resolver",()=>{foreach(int priority in new[]{1,15,30}){Reset();Make();Set("SoloWinOption",priority);Check(LessThan.TryChooseWinner()&&CustomWinnerHolder.WinPriority==priority);}});
 Test("higher priority existing winner is preserved",()=>{Make();ExistingWinner(20);Check(!LessThan.TryChooseWinner()&&CustomWinnerHolder.WinnerTeam==CustomWinner.Tiger);});
 Test("equal priority existing winner is preserved with no joint winner",()=>{Make();ExistingWinner(15);Check(!LessThan.TryChooseWinner()&&CustomWinnerHolder.WinnerTeam==CustomWinner.Tiger&&CustomWinnerHolder.AdditionalWinnerRoles.Count==0);});
 Test("higher LessThan priority overrides existing lower winner",()=>{Make();ExistingWinner(14);Check(LessThan.TryChooseWinner()&&CustomWinnerHolder.WinnerTeam==CustomWinner.LessThan);});
 Test("draw none outro and non host do not become LessThan win",()=>{for(int n=0;n<4;n++){Reset();Make();if(n==0)CustomWinnerHolder.WinnerTeam=CustomWinner.Draw;if(n==1)CustomWinnerHolder.WinnerTeam=CustomWinner.None;if(n==2)GameStates.IsOutro=true;if(n==3)AmongUsClient.Instance.AmHost=false;Check(!LessThan.TryChooseWinner());}});
 Test("final solo result removes accidental additions and role-wide winners",()=>{Make();Check(LessThan.TryChooseWinner());CustomWinnerHolder.WinnerIds.Add(1);CustomWinnerHolder.WinnerRoles.Add(CustomRoles.LessThan);CustomWinnerHolder.AdditionalWinnerRoles.Add(CustomRoles.OtherNeutral);LessThan.FinalizeSoloWinner();Check(CustomWinnerHolder.WinnerIds.SetEquals(new byte[]{0})&&CustomWinnerHolder.WinnerRoles.Count==0&&CustomWinnerHolder.AdditionalWinnerRoles.Count==0&&CustomWinnerHolder.NeutralWinnerIds.SetEquals(new byte[]{0}));});
 Test("later higher-priority winner is not overwritten by finalization",()=>{Make();LessThan.TryChooseWinner();ExistingWinner(30);LessThan.FinalizeSoloWinner();Check(CustomWinnerHolder.WinnerTeam==CustomWinner.Tiger);});
 Test("disposal clears last role ledger and presentation",()=>{var r=Make();r.OnDestroy();Check(!LessThan.TryGetNumber(r.Player,out _)&&r.GetMark(r.Player)=="");});
 Test("invalid self target is not an ordinary kill",()=>{var r=Make();var info=Attempt(r,r.Player);Check(!info.DoKill&&!r.Player.Data.IsDead);});
 Test("multiple rerolls update only each MOD owners number",()=>{var a=Make(12,34,1);var peer=PlayerCatch.GetPlayerById(2);peer.Mod=true;var b=new LessThan(peer);b.Add();Meeting(a,b);Set("LessThanRerollOthers",1);AmongUsClient.Instance.Sent.Clear();((TestRandom)IRandom.Instance).Values=new(new[]{22,44,66});Vote(a);Check(AmongUsClient.Instance.Sent.Single().Values.SequenceEqual(new object[]{(byte)2,true,66})&&AmongUsClient.Instance.Sent.All(m=>m.Target==peer.ClientId));});
 Test("winner network payload contains no secret number ledger",()=>{Make(73,91);Check(LessThan.TryChooseWinner());var writer=new Hazel.MessageWriter();CustomWinnerHolder.WriteTo(writer);Check(!writer.Values.Contains(73)&&!writer.Values.Contains(91));});
 Test("numeric secrets never go to logs",()=>{Make(73,91);Check(Logger.Messages.All(x=>!x.Contains("73")&&!x.Contains("91")));});
 Test("local meeting number is replaced without duplicate or damage to other marks",()=>{var r=Make();Meeting(r);var area=new PlayerVoteArea{PlayerId=0};area.NameText.text="<color=red>FAKE_PLAYER</color> ★"+r.GetMark(r.Player);MeetingHud.Instance.playerStates=new[]{area};Vote(r);Check(area.NameText.text.Contains("(50)")&&!area.NameText.text.Contains("(62)")&&area.NameText.text.Contains("<color=red>FAKE_PLAYER</color> ★"));var before=area.NameText.text;string again=LessThan.ReplaceMeetingNumber(before,r.GetMark(r.Player));Check(before==again);});
 Test("client number RPC refreshes its own meeting row only",()=>{var r=Make();Meeting(r);MeetingHud.Instance.playerStates=new[]{new PlayerVoteArea{PlayerId=0},new PlayerVoteArea{PlayerId=1}};AmongUsClient.Instance.AmHost=false;r.ReceiveRPC(new(true,88));Check(MeetingHud.Instance.playerStates[0].NameText.text.Contains("(88)")&&MeetingHud.Instance.playerStates[1].NameText.text=="FAKE_PLAYER");});
 Test("Vanilla reroll name refresh is explicitly owner-targeted",()=>{var r=new LessThan(PC(1));r.Add();Meeting(r);NameColorManager.Calls.Clear();Vote(r);Check(NameColorManager.Calls.Single().Target==r.Player&&NameColorManager.Calls.Single().Seer==r.Player);Check(LessThan.PrivateMeetingMark(PlayerControl.LocalPlayer,r.Player)=="");});
 Test("private number mark removal preserves unrelated colored numbers",()=>{string other="<color=#D4A5FF>(99)</color>";string old=" <link=\"LessThanSelfNumber\"><color=#D4A5FF>(62)</color></link>";Check(LessThan.ReplaceMeetingNumber(other+old,"")==other);});
 IntegrationAudit.Run(Test,Check);
 Console.WriteLine($"RESULT {passed} passed, {failed} failed (actual LessThan, number/usage state, IKiller and existing winner resolver; Unity/vote transport substitutes)");
 Environment.ExitCode=failed==0?0:1;
 }
}
